import type { GalaxyResponse, MoodResponse, SpotifyUser, TimeRange, TopTracksResponse } from '../api/types'

/** Shape of demo-universe.json, generated by backend/demo/universe.py from the real pipeline. */
export type DemoUniverse = {
  me: SpotifyUser
  ranges: Record<TimeRange, { galaxy: GalaxyResponse; top_tracks: TopTracksResponse; mood: MoodResponse }>
}

let cached: Promise<DemoUniverse> | null = null

/** Loaded on first use, so visitors who never see the demo don't download it. */
export function loadDemoUniverse(): Promise<DemoUniverse> {
  cached ??= import('./demo-universe.json').then((m) => m.default as unknown as DemoUniverse)
  return cached
}
